using System;using System.IO;using System.Reflection;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
class CitationCandidateTests {
 static Type t;static object Call(string n,params object[] a){try{return t.GetMethod(n,BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,a);}catch(TargetInvocationException e){throw e.InnerException;}}static object Get(object o,string n){return o.GetType().GetProperty(n).GetValue(o,null);}static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static void Main(string[] a){try{Run(a);}catch(Exception e){Console.WriteLine("FAIL: "+e.GetType().Name+": "+e.Message);Environment.Exit(1);}}
 static void Run(string[] a){string root=Path.GetFullPath(a[0]);t=Assembly.LoadFrom(Path.Combine(root,"reader.exe")).GetType("MinerULibraryReview");foreach(var p in new[]{new[]{"AppDirectory",root},new[]{"StateDirectory",Path.Combine(root,"state")},new[]{"PapersStateDirectory",Path.Combine(root,"state","papers")},new[]{"LibraryRoot",Path.Combine(root,"library")}})t.GetField(p[0],BindingFlags.NonPublic|BindingFlags.Static).SetValue(null,p[1]);Directory.CreateDirectory(Path.Combine(root,"state","papers"));
 string title="TACSEM: Tactile Sensing, 3-D State Estimation and In-Hand Manipulation of a Soft Hand";
 Check((string)Call("GuessCitationTitle","IEEE/ASME TRANSACTIONS ON MECHATRONICS   1\nTACSEM: Tactile Sensing, 3-D State Estimation\nand In-Hand Manipulation of a Soft Hand\nHui Zhang   , Member, IEEE , Qingyu Wang   , Student Member, IEEE ,\nAbstract")==title,"Keep punctuation and numbers; stop at authors");
 Check((string)Call("GuessCitationTitle","GR-Dexter Technical Report\nByteDance Seed\nFull Author List in Contributions and Acknowledgements\nAbstract")=="GR-Dexter Technical Report","Exclude affiliation and author-list notice");
 Check((string)Call("GuessCitationTitle","World Motion Models:\nFlexible Sequence Modeling of SE(3) Trajectories\nJiahui Lei   Qianqian Wang   Trevor Darrell   Angjoo Kanazawa\nAbstract")=="World Motion Models: Flexible Sequence Modeling of SE(3) Trajectories","Keep title numbers; stop at separated names");
 var cache=(IDictionary)t.GetField("CitationNetworkCache",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);
 string d=Path.Combine(root,"library","2512.24210v1");Directory.CreateDirectory(d);File.WriteAllText(Path.Combine(d,"source.pdf"),"fixture");File.WriteAllText(Path.Combine(d,"pdf-text.txt"),"PDF 文本提取 · 共 1 页\n===== PDF 第 1 / 1 页 =====\nGR-Dexter Technical Report\nByteDance Seed\nFull Author List in Contributions and Acknowledgements\nAbstract\n2026\narXiv:2512.24210v1");
 string feed="<feed xmlns='http://www.w3.org/2005/Atom' xmlns:arxiv='http://arxiv.org/schemas/atom'><entry><id>http://arxiv.org/abs/2512.24210v2</id><title>GR-Dexter Technical Report</title><published>2025-12-30</published><author><name>Ruoshi Wen</name></author><author><name>Guangzeng Chen</name></author></entry></feed>";
 cache["https://export.arxiv.org/api/query?id_list=2512.24210v1"]=feed;
 cache["https://export.arxiv.org/api/query?search_query="+Uri.EscapeDataString("ti:\"GR-Dexter Technical Report\"")+"&max_results=5"]=feed;
 cache["https://api.crossref.org/works?rows=5&query.bibliographic="+Uri.EscapeDataString("GR-Dexter Technical Report") ]="{\"message\":{\"items\":[{\"title\":[\"Unrelated robotic learning\"],\"DOI\":\"10.1234/unrelated\",\"author\":[{\"family\":\"Smith\",\"given\":\"Alice\"}],\"published\":{\"date-parts\":[[2025]]}}]}}";
 Console.WriteLine("Checking fallback candidates");var result=Call("RecognizeCitation","2512.24210v1");Check((string)Get(result,"status")=="review","Version mismatch cannot auto-save");var list=(IList)Get(result,"matches");Check(list.Count==2,"Both sources retained as candidates");Check((string)Get(list[0],"arxiv")=="2512.24210v2","Closest title is first");Check(((string)Get(result,"warning")).Contains("版本"),"Version difference explained");Check(((string)Get(result,"reason")).Contains("请选用"),"Manual candidate review explained");
 try{Call("GetArxivMatch","2512.24210v1");throw new Exception("Manual version check was weakened");}catch(IOException){}
 cache["https://export.arxiv.org/api/query?id_list=2512.24210v1"]=feed.Replace("2512.24210v2","2512.24210v1");
 cache["https://export.arxiv.org/api/query?search_query="+Uri.EscapeDataString("ti:\"GR-Dexter Technical Report\"")+"&max_results=5"]=feed.Replace("2512.24210v2","2512.24210v1");
 Console.WriteLine("Checking exact identifier save");var exact=Call("RecognizeCitation","2512.24210v1");Check((string)Get(exact,"status")=="saved","Exact arXiv identifier and title can auto-save a report whose author list is deferred");
 Console.WriteLine("PASS: TACSEM/GR-Dexter/SE(3) title regressions; fallback candidates ranked across sources; mismatched versions visible but never auto-saved; strict manual lookup preserved.");
 }
}
